const digest = $json.data;
const s = digest.summary;
const cfg = $('Configure Telegram Destinations').first().json;
const destinations = JSON.parse(cfg.destinationsJson || '[]');
const range = `${digest.intervalStartedAt.slice(0, 10)} to ${digest.intervalEndedAt.slice(0, 10)}`;
const text = [
  `UHP Outreach Summary (${range})`,
  `Clients reached out to: ${s.clientsReachedOut} (${s.outreachAttempts} messages)`,
  `Replied: ${s.clientsReplied}`,
  `Response rate: ${s.responseRate}%`,
  `Interested: ${s.interested} | Declined: ${s.declined}`,
  `No response yet: ${s.noResponse}`,
  `New clients added: ${s.newClients}`,
  `Wellness evaluations booked: ${s.wellnessEvaluationsScheduled} | Calls booked: ${s.callsScheduled}`,
].join('\n');
return destinations.map((destination) => ({ json: { ...digest, controlHubUrl: cfg.controlHubUrl, destinationKey: destination.key, chatId: destination.chatId, telegramText: text, idempotencyKey: `outreach-digest:${digest.intervalEndedAt.slice(0, 10)}:${destination.key}` } }));
